        {id:2,name:'Menengah',icon:'🧭',description:'Nilai konteks, identitas, dan cara verifikasi.',minimum:70},
        {id:3,name:'Mahir',icon:'🛡️',description:'Hadapi modus yang lebih rumit dan manipulatif.',minimum:70}
